m<-fread(file.path(V,'00_audit/manifest.csv'));stopifnot(nrow(m)==59,uniqueN(m$patient_id)==42);w(m,'00_input_audit/patient_sample_mapping.csv')
for(t in c(10,20,30)){
 ns<-net(t);w(ns,paste0('tables/network_summary_t',t,'.csv'));pn<-fread(file.path(TD(t),'patient_condition_networks.csv'))[clinical_group!='Normal'];w(pn,paste0('tables/patient_network_t',t,'.csv'))
 # Verify existing patient-condition medians; no change to original aggregation.
 chk<-pn[,.(independent_patients=uniqueN(patient_id[eligible]),median=q(weight),units=sum(eligible)),by=.(sender,receiver)];chk<-merge(chk,ns,by=c('sender','receiver'));stopifnot(all(chk$independent_patients==chk$eligible_patients),all(abs(chk$median-chk$patient_condition_median)<1e-10,na.rm=TRUE));w(chk,paste0('00_input_audit/network_recheck_t',t,'.csv'))
 # Count missing edges remain NA; diagonal is excluded from displayed complete networks.
 sp<-fread(file.path(TD(t),'network_all_specimens.csv'))[clinical_group!='Normal'];pc<-sp[,.(LR_count=q(LR_count),eligible=any(eligible)),by=.(patient_id,dataset,clinical_group,sender,receiver)];cc<-pc[,.(median_count=q(LR_count),n_patients=uniqueN(patient_id[eligible])),by=.(sender,receiver)];w(cc,paste0('tables/network_count_t',t,'.csv'))
 for(kind in c('LR','pathway')){z<-features(kind,t);z<-z[stratification%in%c('tumor_only','tumor_dataset')&sender!=receiver];z<-annotate_dir(z);w(z,paste0('tables/C5_',kind,'_t',t,'.csv.gz'))}
}
# Metadata and all 14 group identities must remain the original v2; no high/low states.
db<-fread(file.path(H,'00_input_audit/DB_interaction_gene_components.csv'));orig<-fread(file.path(V,'00_audit/CellChatDB_full_interactions.csv'));stopifnot(setequal(orig$interaction_id,db$feature));w(db,'00_input_audit/DB_components.csv')
# Category strengths: sum LR probabilities within each eligible specimen, then patient-condition median;
# compositions are per specimen -> patient-condition median, and mean across units for a sum-to-one display.
sp<-fread(file.path(TD(20),'network_all_specimens.csv'))[clinical_group!='Normal'&sender!=receiver&(sender==C5|receiver==C5)]
lr<-fread(file.path(TD(20),'LR_detected_all_specimens.csv.gz'));lr<-lr[clinical_group!='Normal'&sender!=receiver&(sender==C5|receiver==C5)];lr<-merge(lr,db[,.(interaction_id=feature,category=annotation)],by='interaction_id',all.x=TRUE)
cats<-unique(db$annotation);z<-sp[rep(seq_len(.N),each=length(cats))];z[,category:=rep(cats,times=.N/length(cats))];z[,value:=ifelse(eligible,0,NA_real_)];a<-lr[,.(observed=sum(weight)),by=.(specimen_id,sender,receiver,category)];z<-merge(z,a,by=c('specimen_id','sender','receiver','category'),all.x=TRUE);z[eligible&!is.na(observed),value:=observed];z[,fraction:=ifelse(eligible&weight>0,value/weight,NA_real_)];p<-z[,.(strength=q(value),fraction=q(fraction),eligible=any(eligible),positive=any(value>0,na.rm=TRUE)),by=.(patient_id,dataset,clinical_group,sender,receiver,category)];p<-annotate_dir(p);w(p,'tables/category_patient.csv');s<-p[,.(median_strength=q(strength),mean_fraction=if(all(is.na(fraction)))NA_real_ else mean(fraction,na.rm=TRUE),n_patients=uniqueN(patient_id[eligible]),n_fraction_patients=uniqueN(patient_id[!is.na(fraction)])),by=.(sender,receiver,direction,partner,category)];w(s,'tables/category_summary.csv')
# Category decomposition must equal native aggregate network before patient medians.
check<-z[,.(sum_category=if(any(eligible))sum(value,na.rm=TRUE)else NA_real_,network=weight[1]),by=.(specimen_id,sender,receiver)];stopifnot(all(abs(check$sum_category-check$network)<1e-8,na.rm=TRUE));w(check,'00_input_audit/category_sum_check.csv')
# Original common-specimen C5 vs other subgroups. Median of specimen differences, not unmatched medians.
c<-fread(file.path(TD(20),'C5_vs_fibro_common_specimen_strength.csv'))[clinical_group!='Normal'&partner%in%TME];p<-c[,.(C5=q(C5_weight),other_strength=q(other_weight),difference=q(difference),n_specimens=.N),by=.(patient_id,dataset,clinical_group,other,partner,direction)];w(p,'tables/fibro_common_patient_pairs.csv');s<-p[,.(median_difference=q(difference),q25=q(difference,.25),q75=q(difference,.75),n_patients=uniqueN(patient_id),n_units=.N,fraction_C5_greater=mean(difference>0)),by=.(other,partner,direction)];w(s,'tables/fibro_common_summary.csv')
w(data.table(parameter=c('seed','main_threshold','main_condition','threads','inference_rerun','patient_rule','positive_rule'),value=c('123','20','Tumor','1','NO','median within patient x clinical_group, original v2','any eligible specimen positive, original v2')),'00_input_audit/config.csv');writeLines(capture.output(sessionInfo()),file.path(O,'00_input_audit/sessionInfo.txt'));cat('PREPARE COMPLETE\n')
